<script setup lang="ts">
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue'
import { Plus, Search, ChevronLeft, ChevronRight, X, Download, Upload, Pencil, Archive, RefreshCw, ShieldCheck, Phone, Copy, LoaderCircle, Check, Pause, Settings2, UserRoundX, UserRoundCheck, ShieldMinus, ShieldPlus } from 'lucide-vue-next'
import { api } from './api'
const props=defineProps<{page:string;demo:boolean;superadmin:boolean;campaigns:any[]}>()
const emit=defineEmits(['changed','notify'])
const endpoints:Record<string,string>={campaigns:'campaigns',imports:'imports',results:'prospects',exports:'exports',admins:'administrators',audit:'audit',exclusions:'suppressions',calls:'calls'}
const data=ref<any[]>([]),count=ref(0),index=ref(1),loading=ref(false),error=ref(''),search=ref(''),filterCampaign=ref(''),filterStatus=ref('')
const dialog=ref(''),saving=ref(false),form=ref<any>({}),detail=ref<any>(null),history=ref<any>(null),preview=ref<any>(null),file=ref<File|null>(null)
const columns=ref(['name','reference','e164','validity','line_status','compliance','reason','checked_at'])
const allColumns=['name','reference','raw_phone','e164','validity','line_status','carrier','line_type','compliance','compliance_reason','reason','checked_at']
const columnLabels:Record<string,string>={name:'Nom',reference:'Référence',raw_phone:'Numéro source',e164:'Numéro E.164',validity:'Validité',line_status:'Statut de ligne',carrier:'Opérateur',line_type:'Type de ligne',compliance:'Autorisation',compliance_reason:'Motif de l’autorisation',reason:'Justification technique',checked_at:'Date de vérification'}
const settingsData=ref<any>(null),mfa=ref<any>(null),backup=ref<string[]>([]),invite=ref(''),choices=ref<any[]>([]),notifications=ref<any[]>([])
const modalRoot=ref<HTMLElement|null>(null)
let timer:ReturnType<typeof setInterval>|undefined, previousFocus:HTMLElement|null=null, sequence=0
const title=computed(()=>({campaigns:'Campagnes',imports:'Imports',results:'Numéros & résultats',exports:'Exports',admins:'Administrateurs',audit:'Journal d’audit',exclusions:'Liste d’exclusion',calls:'Campagnes d’appels',settings:'Paramètres',account:'Mon compte'} as Record<string,string>)[props.page])
const canCreate=computed(()=>['campaigns','imports','exports','admins','exclusions','calls'].includes(props.page))
const campaignName=(id:number)=>choices.value.find(c=>c.id===id)?.name||props.campaigns.find(c=>c.id===id)?.name||`Campagne ${id}`
const label=(s:string)=>({valid:'Valide',invalid:'Invalide',indeterminate:'Indéterminée',unknown:'Inconnue',review:'À examiner',allowed:'Autorisé',forbidden:'Interdit',completed:'Terminé',draft:'Brouillon',active:'En cours',archived:'Archivée',queued:'En attente',pending:'En attente',running:'En cours',error:'Erreur',expired:'Expiré',stopped:'Arrêté'} as Record<string,string>)[s]||s
const date=(value:string)=>value?new Date(value).toLocaleString('fr-FR'):'—'
const qs=computed(()=>new URLSearchParams({page:String(index.value),page_size:'25',...(search.value?{search:search.value}:{}),...(filterCampaign.value?{campaign:filterCampaign.value}:{}),...(filterStatus.value?{[props.page==='results'?'validity':'status']:filterStatus.value}:{})}).toString())
async function loadChoices(){if(props.demo){choices.value=props.campaigns;return} let path='campaigns/?page_size=100';const result:any[]=[];while(path){const r=await api(path);result.push(...r.results);path=r.next?new URL(r.next).pathname.replace('/api/','')+new URL(r.next).search:''}choices.value=result}
async function load(silent=false){
  const seq=++sequence
  if(!silent)loading.value=true
  try{
    if(props.demo){
      const examples:Record<string,any[]>={campaigns:props.campaigns,imports:[{id:1,campaign:1,status:'completed',report:{total:4500,valid:4216,duplicates:218,invalid:66}}],results:[{id:1,name:'Contact fictif A',e164:'+14165550123',raw_phone:'4165550123',validity:'valid',line_status:'unknown',compliance:'review',reason:'Validation locale',campaign:1},{id:2,name:'Contact fictif B',e164:'+15145550124',validity:'valid',line_status:'unknown',compliance:'review',campaign:1}],exports:[{id:1,campaign:1,format:'csv',status:'completed',expires_at:'2026-10-14T20:00:00Z'}],admins:[{id:1,username:'Alex Martin',email:'demo@example.com',is_active:true,mfa_enabled:true,is_superuser:true}],audit:[{id:1,action:'import.confirmed',object_id:'1',created_at:'2026-10-13T20:00:00Z'}],exclusions:[],calls:[]}
      data.value=(examples[props.page]||[]).filter(r=>!search.value||JSON.stringify(r).toLowerCase().includes(search.value.toLowerCase()));count.value=data.value.length
      if(props.page==='settings')settingsData.value={settings:{lookup_cache_hours:168,lookup_rate:5,export_hours:24,import_retention_days:90,currency:'CAD'},integrations:{lookup_configured:false,lookup_enabled:false,voice_enabled:false,smtp_configured:false,s3_enabled:false,mfa_encryption_configured:false,development:true},tasks:{waiting:0,failed:0}}
      if(props.page==='account')mfa.value={username:'Alex Martin',mfa_enabled:true,backup_remaining:10}
      return
    }
    const result=await api(props.page==='settings'?'settings/':props.page==='account'?'auth/session/':`${endpoints[props.page]}/?${qs.value}`)
    if(seq!==sequence)return
    if(props.page==='settings')settingsData.value=result
    else if(props.page==='account')mfa.value=result
    else{data.value=Array.isArray(result)?result.filter(r=>!search.value||[r.username,r.email].join(' ').toLowerCase().includes(search.value.toLowerCase())):result.results;count.value=Array.isArray(result)?data.value.length:result.count}
    if(!silent)error.value=''
  }catch(e:any){if(seq===sequence)error.value=e.message}finally{if(seq===sequence)loading.value=false}
}
async function refresh(){await load();await loadChoices();emit('changed')}
function protect(){if(props.demo){emit('notify','Aperçu : connectez-vous pour enregistrer vos changements.');return false}return true}
async function show(kind:string,entity?:any){previousFocus=document.activeElement as HTMLElement;dialog.value=kind;error.value='';invite.value='';backup.value=[];detail.value=entity||null;history.value=null;preview.value=null;file.value=null
  form.value=entity?{...entity}:{name:'',purpose:'',source:'',budget:'10',campaign:filterCampaign.value||String(choices.value.find(c=>c.status!=='archived')?.id||''),format:'csv',validity:'',compliance:'review',reason:'',e164:'',username:'',email:'',password:'',code:'',basis:'',evidence:'',expires_at:'',sheet:''}
  await nextTick();modalRoot.value?.querySelector<HTMLElement>('input,select,button')?.focus()
  if(kind==='detail'&&protect()){try{history.value=await api(`prospects/${entity.id}/history/`)}catch(e:any){error.value=e.message}}
  if(kind==='eligibility'&&protect()){try{history.value=await api(`calls/${entity.id}/eligibility/`)}catch(e:any){error.value=e.message}}
}
function close(){dialog.value='';invite.value='';backup.value=[];previousFocus?.focus()}
async function execute(path:string,body:any,method='POST'){if(!protect())return null;return api(path,{method,body:body instanceof FormData?body:JSON.stringify(body)})}
async function save(){saving.value=true;error.value='';try{
  let result:any
  if(dialog.value==='campaign')result=await execute(detail.value?`campaigns/${detail.value.id}/`:'campaigns/',{name:form.value.name,purpose:form.value.purpose,source:form.value.source,budget:form.value.budget},detail.value?'PATCH':'POST')
  if(dialog.value==='archive')result=await execute(`campaigns/${detail.value.id}/archive/`,{})
  if(dialog.value==='export')result=await execute('exports/',{campaign:Number(form.value.campaign),format:form.value.format,columns:columns.value,filters:{...(form.value.validity?{validity:form.value.validity}:{})}})
  if(dialog.value==='admin'){result=await execute('administrators/',{username:form.value.username,email:form.value.email,invite:true});if(result?.invitation){invite.value=`${location.origin}/reset-password?uid=${result.invitation.uid}&token=${result.invitation.token}`;await load();return}}
  if(dialog.value==='exclusion')result=await execute('suppressions/',{e164:form.value.e164,reason:form.value.reason})
  if(dialog.value==='consent')result=await execute('consents/',{prospect:detail.value.id,basis:form.value.basis,evidence:form.value.evidence,expires_at:new Date(form.value.expires_at).toISOString()})
  if(dialog.value==='classify')result=await execute(`prospects/${detail.value.id}/classify/`,{compliance:form.value.compliance,reason:form.value.reason})
  if(dialog.value==='call')result=await execute('calls/',{campaign:Number(form.value.campaign),configuration:{purpose:form.value.purpose}})
  if(dialog.value==='import'){
    if(!preview.value){if(!file.value)throw new Error('Choisissez un fichier');const body=new FormData();body.append('campaign',form.value.campaign);body.append('file',file.value);result=await execute('imports/',body);if(result){preview.value=result;form.value.phone=result.headers.find((h:string)=>/phone|tel/i.test(h))||result.headers[0];form.value.nameColumn='';form.value.referenceColumn='';form.value.sheet=result.sheets[0]||''}return}
    result=await execute(`imports/${preview.value.id}/confirm/`,{mapping:{phone:form.value.phone,...(form.value.nameColumn?{name:form.value.nameColumn}:{}),...(form.value.referenceColumn?{reference:form.value.referenceColumn}:{})}})
  }
  if(result){close();await refresh();emit('notify','Votre demande a été enregistrée.')}
}catch(e:any){error.value=e.message}finally{saving.value=false}}
async function sheetPreview(){if(!preview.value)return;try{preview.value=await execute(`imports/${preview.value.id}/preview/`,{sheet:form.value.sheet});form.value.phone=preview.value.headers[0];form.value.nameColumn='';form.value.referenceColumn=''}catch(e:any){error.value=e.message}}
async function action(path:string,body:any={}){try{if(await execute(path,body)){await refresh();emit('notify','Action enregistrée.')}}catch(e:any){error.value=e.message}}
async function toggleAdmin(row:any){try{if(await execute('administrators/',{id:row.id,is_active:!row.is_active},'PATCH'))await load()}catch(e:any){error.value=e.message}}
async function changeRole(row:any){try{if(await execute('administrators/',{id:row.id,role:row.is_superuser?'administrator':'superadministrator'},'PATCH'))await load()}catch(e:any){error.value=e.message}}
async function settingsSave(){try{if(await execute('settings/',settingsData.value.settings,'PATCH')){emit('notify','Paramètres enregistrés.');await load()}}catch(e:any){error.value=e.message}}
async function enroll(){try{if(!protect())return;const result=await api('auth/mfa/',{method:'POST',body:'{"action":"enroll"}'});await show('mfa');form.value=result}catch(e:any){error.value=e.message}}
async function confirmMfa(){try{const result=await execute('auth/mfa/',{code:form.value.code});if(result){backup.value=result.backup_codes;await load();dialog.value='backup'}}catch(e:any){error.value=e.message}}
async function backupGenerate(){try{const result=await execute('auth/mfa/',{action:'backup',code:form.value.code,password:form.value.password});if(result){backup.value=result.backup_codes;dialog.value='backup';form.value.password='';await load()}}catch(e:any){error.value=e.message}}
async function copy(text:string){try{await navigator.clipboard.writeText(text);emit('notify','Copié dans le presse-papiers.')}catch{emit('notify','Sélectionnez le texte pour le copier.')}}
function keydown(event:KeyboardEvent){if(!dialog.value)return;if(event.key==='Escape')close();if(event.key==='Tab'){const items=Array.from(modalRoot.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input,select,textarea,a[href]')||[]);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
watch(()=>props.page,()=>{index.value=1;search.value='';filterCampaign.value='';filterStatus.value='';dialog.value='';load()})
onMounted(async()=>{document.addEventListener('keydown',keydown);await loadChoices();await load();timer=setInterval(()=>{if(!document.hidden&&!dialog.value&&!props.demo&&['imports','exports','campaigns','calls'].includes(props.page))load(true)},10000)})
onUnmounted(()=>{clearInterval(timer);document.removeEventListener('keydown',keydown);sequence++})
defineExpose({show,refresh})
</script>

<template>
  <div class="page-heading"><div><h1>{{title}}</h1><p>{{page==='account'?'Vos accès et votre sécurité.':'Gérez les données et les opérations de votre espace.'}}</p></div><button v-if="canCreate" class="primary" @click="show(({campaigns:'campaign',imports:'import',exports:'export',admins:'admin',exclusions:'exclusion',calls:'call'} as any)[page])"><Plus :size="18"/>{{page==='imports'?'Importer un fichier':page==='admins'?'Inviter un administrateur':'Ajouter'}}</button></div>
  <p v-if="error&&!dialog" class="error" role="alert">{{error}}</p>
  <section v-if="page==='settings' && settingsData" class="card settings-card"><div class="card-header"><h2>Traitements et conservation</h2></div><form class="settings-form" @submit.prevent="settingsSave"><label>Cache Lookup (heures)<input v-model.number="settingsData.settings.lookup_cache_hours" type="number" min="1" max="8760" required></label><label>Requêtes Lookup / seconde<input v-model.number="settingsData.settings.lookup_rate" type="number" min="1" max="50" required></label><label>Disponibilité des exports (heures)<input v-model.number="settingsData.settings.export_hours" type="number" min="1" max="168" required></label><label>Conservation des imports (jours)<input v-model.number="settingsData.settings.import_retention_days" type="number" min="1" max="3650" required></label><label>Devise du fournisseur<select v-model="settingsData.settings.currency"><option>CAD</option><option>USD</option><option>EUR</option></select></label><div><button class="primary">Enregistrer</button></div></form><div class="card-header"><h2>Connexions externes</h2><span class="pill muted">Identifiants à ajouter côté serveur</span></div><div class="integration-grid"><div v-for="(value,key) in settingsData.integrations" :key="key"><strong>{{({lookup_configured:'Identifiants Twilio',lookup_enabled:'Lookup activé',voice_enabled:'Appels activés',smtp_configured:'SMTP',s3_enabled:'Stockage objet',mfa_encryption_configured:'Clé de chiffrement MFA',development:'Mode développement'} as any)[key]}}</strong><span :class="['pill',value?'green-pill':'muted']">{{value?'Oui':'Non'}}</span></div></div><p class="panel-note">{{settingsData.tasks.waiting}} tâches attendent une livraison · {{settingsData.tasks.failed}} tâches nécessitent un examen.</p></section>
  <section v-else-if="page==='account' && mfa" class="card"><div class="card-header"><h2>Sécurité du compte {{mfa.username}}</h2><ShieldCheck :size="22"/></div><div class="account-body"><strong>Authentification à deux facteurs</strong><p>{{mfa.mfa_enabled?'Votre compte utilise un code TOTP à chaque connexion.':'Ajoutez une deuxième protection à votre compte.'}}</p><button v-if="!mfa.mfa_enabled" class="primary" @click="enroll">Activer le MFA</button><template v-else><p>{{mfa.backup_remaining||0}} codes de secours disponibles.</p><button class="secondary" @click="show('backup-auth')">Renouveler les codes de secours</button></template></div></section>
  <section v-else class="card"><div class="table-toolbar"><form class="search-field" @submit.prevent="index=1;load()"><Search :size="18"/><input v-model="search" :placeholder="page==='audit'?'Rechercher une opération':'Rechercher…'" aria-label="Recherche"><button class="search-submit" aria-label="Lancer la recherche"><ChevronRight :size="17"/></button></form><select v-if="['imports','results','exports'].includes(page)" v-model="filterCampaign" aria-label="Filtrer par campagne" @change="index=1;load()"><option value="">Toutes les campagnes</option><option v-for="c in choices" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-if="['campaigns','results'].includes(page)" v-model="filterStatus" aria-label="Filtrer par statut" @change="index=1;load()"><option value="">Tous les statuts</option><option v-for="s in page==='results'?['valid','invalid','indeterminate']:['draft','active','archived']" :key="s" :value="s">{{label(s)}}</option></select><button class="icon-button" aria-label="Actualiser" @click="refresh"><RefreshCw :size="18" :class="{spin:loading}"/></button></div>
    <div class="table-scroll"><table><thead><tr v-if="page==='campaigns'"><th>Campagne</th><th>Statut</th><th>Qualification</th><th>Budget / Réserve estimée</th><th>Actions</th></tr><tr v-else-if="page==='results'"><th>Contact</th><th>Numéro</th><th>Validité</th><th>Joignabilité</th><th>Conformité</th><th></th></tr><tr v-else-if="page==='imports'"><th>Import</th><th>Statut</th><th>Rapport de nettoyage</th><th>Actions</th></tr><tr v-else-if="page==='exports'"><th>Campagne / Format</th><th>Statut</th><th>Expiration</th><th>Actions</th></tr><tr v-else-if="page==='admins'"><th>Administrateur</th><th>Rôle</th><th>État</th><th>MFA</th><th>Actions</th></tr><tr v-else-if="page==='exclusions'"><th>Numéro exclu</th><th>Motif</th><th>Date</th></tr><tr v-else-if="page==='calls'"><th>Préparation</th><th>Statut</th><th>Scénario</th><th>Actions</th></tr><tr v-else><th>Opération</th><th>Objet</th><th>Date</th><th>Détails</th></tr></thead><tbody>
      <tr v-for="r in data" :key="r.id"><template v-if="page==='campaigns'"><td class="strong">{{r.name}}<small>{{r.source}}</small></td><td><span class="pill muted">{{label(r.status)}}</span></td><td><span>{{r.progress?.checked||0}} / {{r.progress?.total||0}}</span><div class="mini-progress"><i :style="{width:(r.progress?.percent||0)+'%'}"></i></div><small>{{r.progress?.pending||0}} en attente · {{r.progress?.errors||0}} erreurs</small></td><td>{{r.budget}} / {{r.spent}}</td><td class="row-actions"><button class="text-button" :disabled="r.status==='archived'" @click="action(`campaigns/${r.id}/lookup/`)">Vérifier</button><button class="icon-button" aria-label="Modifier la campagne" @click="show('campaign',r)"><Pencil :size="16"/></button><button class="icon-button" :disabled="r.status==='archived'" aria-label="Archiver la campagne" @click="show('archive',r)"><Archive :size="16"/></button></td></template>
      <template v-else-if="page==='results'"><td>{{r.name||'Sans nom'}}<small>{{r.reference}}</small></td><td>{{r.e164||r.raw_phone}}</td><td><span :class="['pill',r.validity==='valid'?'green-pill':'orange-pill']">{{label(r.validity)}}</span></td><td>{{label(r.line_status)}}</td><td>{{label(r.compliance)}}</td><td><button class="text-button" @click="show('detail',r)">Voir la fiche <ChevronRight :size="15"/></button></td></template>
      <template v-else-if="page==='imports'"><td>{{campaignName(r.campaign)}}<small>Import #{{r.id}}</small></td><td><span class="pill muted">{{label(r.status)}}</span></td><td>{{r.report?.total||0}} lignes · {{r.report?.valid||0}} valides<small>{{r.report?.duplicates||0}} doublons · {{r.report?.invalid||0}} invalides {{r.report?.error||''}}</small></td><td><a v-if="!demo&&r.status==='completed'" class="text-button" :href="`/api/imports/${r.id}/report/`">Rapport CSV</a><button v-if="r.status==='error'" class="text-button" @click="action(`imports/${r.id}/retry/`)">Relancer</button></td></template>
      <template v-else-if="page==='exports'"><td>{{campaignName(r.campaign)}}<small>{{r.format.toUpperCase()}} · Export #{{r.id}}</small></td><td><span class="pill muted">{{label(r.status)}}</span><small>{{r.error}}</small></td><td>{{date(r.expires_at)}}</td><td><a v-if="!demo&&r.status==='completed'&&new Date(r.expires_at)>new Date()" class="text-button" :href="`/api/exports/${r.id}/download/`">Télécharger <Download :size="15"/></a><span v-else class="subtle">{{r.status==='completed'?'Expiré ou aperçu':'En attente'}}</span></td></template>
      <template v-else-if="page==='admins'"><td>{{r.username}}<small>{{r.email}}</small></td><td>{{r.is_superuser?'Super administrateur':'Administrateur'}}</td><td><span class="pill muted">{{r.is_active?'Actif':'Suspendu'}}</span></td><td>{{r.mfa_enabled?'Activé':'Non activé'}}</td><td><div class="admin-actions"><button :class="['admin-action',r.is_active?'danger':'reactivate']" :aria-label="r.is_active?'Suspendre cet administrateur':'Réactiver cet administrateur'" :title="r.is_active?'Suspendre cet administrateur':'Réactiver cet administrateur'" @click="toggleAdmin(r)"><component :is="r.is_active?UserRoundX:UserRoundCheck" :size="18" stroke-width="1.8"/></button><button class="admin-action" :disabled="!r.is_superuser&&!r.mfa_enabled" :aria-label="r.is_superuser?'Passer au rôle administrateur':'Passer au rôle super administrateur'" :title="!r.is_superuser&&!r.mfa_enabled?'Activez le MFA avant de promouvoir ce compte':r.is_superuser?'Passer au rôle administrateur':'Passer au rôle super administrateur'" @click="changeRole(r)"><component :is="r.is_superuser?ShieldMinus:ShieldPlus" :size="18" stroke-width="1.8"/></button></div></td></template>
      <template v-else-if="page==='exclusions'"><td>{{r.e164}}</td><td class="wrap-cell">{{r.reason}}</td><td>{{date(r.created_at)}}</td></template>
      <template v-else-if="page==='calls'"><td>{{campaignName(r.campaign)}}<small>Préparation #{{r.id}}</small></td><td>{{label(r.status)}}</td><td class="wrap-cell">{{r.configuration?.purpose||'À documenter'}}</td><td class="row-actions"><button class="text-button" @click="show('eligibility',r)">Admissibilité</button><button class="icon-button" aria-label="Arrêter la préparation" @click="action(`calls/${r.id}/stop/`)"><Pause :size="16"/></button></td></template>
      <template v-else><td>{{r.action}}</td><td>{{r.object_id||'—'}}</td><td>{{date(r.created_at)}}</td><td><button class="text-button" @click="show('audit-detail',r)">Consulter</button></td></template></tr>
    </tbody></table></div><div v-if="!data.length" class="empty-state"><Search :size="28"/><strong>{{loading?'Chargement…':'Aucun résultat'}}</strong><p>{{demo?'Exemple de données, aucune modification enregistrée.':'Modifiez vos filtres ou ajoutez votre première donnée.'}}</p></div><footer class="pagination"><span>{{count}} résultats · page {{index}} / {{Math.max(1,Math.ceil(count/25))}}</span><div><button class="secondary" :disabled="index===1" @click="index--;load()"><ChevronLeft :size="15"/> Précédent</button><button class="secondary" :disabled="index*25>=count" @click="index++;load()">Suivant <ChevronRight :size="15"/></button></div></footer>
  </section>
  <p v-if="page==='calls'" class="panel-note">Vous pouvez préparer les campagnes et contrôler leur admissibilité. Les appels réels attendent la configuration fournisseur et la validation de votre scénario.</p>
  <div v-if="dialog" class="modal-backdrop" @click.self="close"><section ref="modalRoot" class="modal workflow-modal" role="dialog" aria-modal="true" aria-labelledby="workflow-title"><header><h2 id="workflow-title">{{({campaign:detail?'Modifier la campagne':'Nouvelle campagne',archive:'Archiver la campagne',import:'Importer une liste',export:'Créer un export',admin:'Inviter un administrateur',exclusion:'Ajouter une exclusion',detail:'Fiche du contact',consent:'Consigner une preuve',classify:'Décision administrative',call:'Préparer les appels',eligibility:'Contrôle d’admissibilité',mfa:'Activer le MFA',backup:'Vos codes de secours','backup-auth':'Renouveler les codes','audit-detail':'Détail de l’opération'} as any)[dialog]}}</h2><button class="icon-button" aria-label="Fermer" @click="close"><X :size="21"/></button></header><p v-if="error" class="error" role="alert">{{error}}</p>
    <template v-if="dialog==='detail'"><dl class="detail-list"><dt>Contact</dt><dd>{{detail.name||'Sans nom'}}</dd><dt>Numéro</dt><dd>{{detail.e164||detail.raw_phone}}</dd><dt>Validité</dt><dd>{{label(detail.validity)}} · {{detail.reason}}</dd><dt>Conformité</dt><dd>{{label(detail.compliance)}} · {{detail.compliance_reason||'Décision à documenter'}}</dd><dt>Exclusion</dt><dd>{{history?.suppressed?'Numéro exclu':'Aucune exclusion trouvée'}}</dd></dl><div class="row-actions"><button class="secondary" @click="show('consent',detail)">Ajouter une preuve</button><button class="secondary" @click="show('classify',detail)">Qualifier l’autorisation</button></div><h3 class="detail-subtitle">Historique Lookup</h3><p v-if="!history?.lookup?.length" class="subtle">Aucune vérification fournisseur.</p><div v-for="check in history?.lookup||[]" :key="check.id" class="history-item">{{date(check.created_at)}} · {{label(check.status)}}<small>{{check.error||'Twilio Lookup'}} · {{check.cost}} estimé</small></div><h3 class="detail-subtitle">Preuves et sources</h3><div v-for="proof in history?.consents||[]" :key="proof.id" class="history-item"><strong>{{proof.basis}}</strong><p>{{proof.evidence}}</p><small>Expiration : {{date(proof.expires_at)}}</small></div><p class="panel-note">{{history?.sources?.length||0}} occurrences sources conservées pour l’audit.</p></template>
    <template v-else-if="dialog==='eligibility'"><p class="panel-note">{{history?.eligible||0}} contacts admissibles sur {{history?.total||0}}. Aucun appel n’est émis.</p><div v-for="r in history?.decisions||[]" :key="r.prospect" class="history-item"><strong>{{r.e164||`Contact ${r.prospect}`}}</strong><small>{{r.eligible?'Admissible sous réserve du scénario':r.reasons.join(' · ')}}</small></div></template>
    <template v-else-if="dialog==='audit-detail'"><dl class="detail-list"><dt>Acteur</dt><dd>{{detail.actor||'Anonyme'}}</dd><dt>Objet</dt><dd>{{detail.object_id}}</dd></dl><pre class="code-panel">{{JSON.stringify(detail.metadata,null,2)}}</pre></template>
    <template v-else-if="dialog==='backup'"><p class="panel-note">Chaque code est utilisable une seule fois. Conservez-les dans un coffre privé. Ils ne seront plus affichés.</p><div class="backup-grid"><code v-for="value in backup" :key="value">{{value}}</code></div><button class="secondary full-width" @click="copy(backup.join('\n'))"><Copy :size="16"/> Copier les codes</button></template>
    <template v-else-if="dialog==='mfa'"><p class="panel-note">Scannez ce QR code avec votre application d’authentification.</p><img class="mfa-qr" :src="form.qr" alt="QR code de configuration MFA"><code class="secret-text">{{form.secret}}</code><form @submit.prevent="confirmMfa"><label>Code de confirmation<input v-model="form.code" inputmode="numeric" required pattern="[0-9]{6}" placeholder="6 chiffres"></label><button class="primary full-width">Activer</button></form></template>
    <form v-else-if="dialog==='backup-auth'" @submit.prevent="backupGenerate"><label>Mot de passe actuel<input v-model="form.password" type="password" autocomplete="current-password" required></label><label>Nouveau code MFA<input v-model="form.code" inputmode="numeric" required pattern="[0-9]{6}"></label><p class="panel-note">Les anciens codes de secours seront remplacés.</p><button class="primary full-width">Générer mes codes</button></form>
    <form v-else @submit.prevent="save">
      <template v-if="dialog==='campaign'"><label>Nom<input v-model="form.name" required maxlength="200"></label><label>Provenance<input v-model="form.source" required maxlength="250"></label><label>Finalité<textarea v-model="form.purpose" required></textarea></label><label>Budget<input v-model="form.budget" type="number" min="0" step="0.01" required></label></template>
      <template v-if="['import','export','call'].includes(dialog)"><label>Campagne<select v-model="form.campaign" required :disabled="!!preview"><option value="" disabled>Choisir une campagne</option><option v-for="c in choices.filter(c=>dialog==='export'||c.status!=='archived')" :key="c.id" :value="c.id">{{c.name}}</option></select></label></template>
      <template v-if="dialog==='import'"><label v-if="!preview" class="upload-zone"><Upload :size="28"/><strong>CSV ou Excel · 20 Mo maximum</strong><input type="file" accept=".csv,.xlsx" required @change="file=($event.target as HTMLInputElement).files?.[0]||null"></label><template v-else><label v-if="preview.sheets.length">Feuille Excel<select v-model="form.sheet" @change="sheetPreview"><option v-for="s in preview.sheets" :key="s">{{s}}</option></select></label><p class="panel-note">{{preview.rows}} lignes détectées.</p><label>Téléphone<select v-model="form.phone" required><option v-for="h in preview.headers" :key="h">{{h}}</option></select></label><label>Nom<select v-model="form.nameColumn"><option value="">Ne pas importer</option><option v-for="h in preview.headers" :key="h">{{h}}</option></select></label><label>Référence<select v-model="form.referenceColumn"><option value="">Ne pas importer</option><option v-for="h in preview.headers" :key="h">{{h}}</option></select></label><div class="table-scroll preview-table"><table><thead><tr><th v-for="h in preview.headers" :key="h">{{h}}</th></tr></thead><tbody><tr v-for="(r,i) in preview.preview" :key="i"><td v-for="h in preview.headers" :key="h">{{r[h]}}</td></tr></tbody></table></div></template></template>
      <template v-if="dialog==='export'"><label>Format<select v-model="form.format"><option value="csv">CSV</option><option value="xlsx">Excel XLSX</option></select></label><label>Validité<select v-model="form.validity"><option value="">Tous les résultats</option><option value="valid">Valides</option><option value="invalid">Invalides</option></select></label><fieldset class="column-options"><legend>Colonnes de l’export</legend><label v-for="col in allColumns" :key="col"><input v-model="columns" type="checkbox" :value="col">{{columnLabels[col]}}</label></fieldset></template>
      <template v-if="dialog==='admin'"><template v-if="invite"><p class="panel-note">Compte créé. Transmettez ce lien par un canal privé. Il permet de définir le mot de passe.</p><textarea :value="invite" readonly aria-label="Lien d’invitation"></textarea><button type="button" class="secondary full-width" @click="copy(invite)"><Copy :size="16"/> Copier le lien</button></template><template v-else><label>Identifiant<input v-model="form.username" required maxlength="150"></label><label>Email<input v-model="form.email" type="email" required></label><p class="panel-note">Le compte reçoit un lien privé de définition de mot de passe ; aucun mot de passe partagé.</p></template></template>
      <template v-if="dialog==='exclusion'"><label>Numéro canadien<input v-model="form.e164" required placeholder="+14165550123"></label><label>Motif<textarea v-model="form.reason" required></textarea></label></template>
      <template v-if="dialog==='consent'"><label>Base d’autorisation<input v-model="form.basis" required></label><label>Preuve et provenance<textarea v-model="form.evidence" required></textarea></label><label>Expiration<input v-model="form.expires_at" type="datetime-local" required></label></template>
      <template v-if="dialog==='classify'"><label>Décision<select v-model="form.compliance"><option value="review">À examiner</option><option value="allowed">Autorisé</option><option value="forbidden">Interdit</option></select></label><label>Justification<textarea v-model="form.reason" minlength="10" required></textarea></label><p class="panel-note">Une autorisation exige une preuve encore valide et l’absence d’exclusion. Elle ne déclenche aucun appel.</p></template>
      <template v-if="dialog==='archive'"><p class="panel-note">Archiver « {{detail.name}} » conserve ses résultats et bloque de nouvelles vérifications.</p></template>
      <template v-if="dialog==='call'"><label>Scénario prévu<textarea v-model="form.purpose" required placeholder="Finalité, type de message et règles d’autorisation"></textarea></label></template>
      <button v-if="!invite" class="primary full-width" :disabled="saving||(dialog==='export'&&!columns.length)"><LoaderCircle v-if="saving" :size="17" class="spin"/>{{saving?'Enregistrement…':dialog==='import'&&!preview?'Prévisualiser':'Confirmer'}}</button>
    </form>
  </section></div>
</template>
